NAME = 'ACV: A Conservative Version'
BOOK = 'Zephaniah'

CHAPTERS = {
    1: {
        1: 'Beseda Gospodova, ki je prišla Zefaniju, sinu Kušija, sina Gedalija, sina Amarija, sina Hezekija, v dneh Josija, sina Amonovega, kralja Judovega.',
        2: 'Docela pokončam vse s površja zemlje, govori Gospod.',
        3: 'Pokončam ljudi in živino, pokončam ptice nebeške in ribe morske in pohujševanje z brezbožniki vred; in iztrebim ljudi s površja zemlje, govori Gospod.',
        4: 'In iztegnem roko zoper Judo in zoper vse prebivalce v Jeruzalemu; in iztrebim ostanek Baala iz tega kraja, imena malikovalskih svečenikov z duhovniki vred,',
        5: 'in tiste, ki se poklanjajo na strehah vojski nebeški, in molilce, ki prisegajo Gospodu in prisegajo pri Malkomu;',
        6: 'in nje, ki odstopajo od Gospoda in ki ne iščejo Gospoda in po njem ne vprašujejo.',
        7: 'Molčite pred obličjem Gospoda Jehove! kajti blizu je dan Gospodov; ker pripravil je Gospod klalno daritev, posvetil je svoje povabljence.',
        8: 'In zgodi se v dan klalne daritve Gospodove, da bom kaznoval poglavarje in sinove kraljeve in vse, ki se oblačijo v inozemsko obleko.',
        9: 'In kaznoval bom tisti dan vsakega, ki skače čez prag, vse, ki napolnjujejo gospodarja svojega hišo s silovitostjo in prevaro.',
        10: 'In tisti dan, govori Gospod, se bo slišalo vpitje od Ribjih vrat in tuljenje od dolnjega mesta in veliko podiranje od hribov.',
        11: 'Tulite, prebivalci v Maktešu! kajti uničeno je vse trgovsko ljudstvo, iztrebljeni so vsi, ki so bili obremenjeni s srebrom.',
        12: 'In zgodi se tisti čas, da preiščem Jeruzalem s svetilnicami, in kaznoval bom može, ki počivajo na svojih drožeh, ki govore v srcu svojem: Gospod ne stori nič dobrega, pa tudi nič hudega.',
        13: 'In njih imetje bode v plen in njih hiše v pustoto; in zidali bodo hiše, a ne bodo prebivali v njih, in sadili vinograde, a ne bodo pili vina iz njih.',
        14: 'Blizu je veliki dan Gospodov, blizu je in silno hiti. Čuj, dan Gospodov! bridko vpije tam junak.',
        15: 'Ta dan je dan srda, dan stiske in nadloge, dan pustote in pustošenja, dan teme in mraka, dan oblakov in noči oblačne,',
        16: 'dan trombe in bojnega vpitja zoper trdna mesta in zoper visoke utrdbe.',
        17: 'In stiskal bom ljudi, da bodo hodili kakor slepci, ker so grešili zoper Gospoda; in njih kri se razmeče kakor prah in njih meso kakor blato.',
        18: 'Tudi njih srebro, tudi njih zlato jih ne bo moglo rešiti ob dnevi jeze Gospodove; in z ognjem gorečnosti njegove bo vsa dežela požrta; zakaj konec, nagel konec naredi vsem prebivalcem dežele.',
    },
    2: {
        1: 'Zberite se, da, zberite se, o narod brezsramni,',
        2: 'preden se uresniči, kar je ukrenjeno (tisti dan poleti mimo kakor pleve), preden pride nad vas togota srda Gospodovega, preden pride nad vas dan jeze Gospodove!',
        3: 'Iščite Gospoda, vsi krotki v deželi, ki ste vršili sodbo njegovo; iščite pravičnost, iščite ponižnost, morda doboste skrivališče ob dnevi jeze Gospodove!',
        4: 'Kajti Gaza bo opuščena in Askelon bo puščava, iz Asdoda preženo prebivalce ob belem dne in Ekron bo izruvan.',
        5: 'Gorje prebivalcem v pokrajini ob morju, narodu Keretejcev! Beseda Gospodova je zoper tebe, o Kanaan, dežela Filistejcev! pogubim te, da ne bode prebivalca!',
        6: 'In pokrajina ob morju postane pašnik s kočami za pastirje in z ograjami za drobnico;',
        7: 'in bode pokrajina za ostanek hiše Judove: po njej bodo pasli, v hišah askelonskih bodo zvečer počivali; kajti obišče jih Gospod, njih Bog, in nazaj pripelje njih ujetništvo.',
        8: 'Slišal sem zasmehovanje Moabovo in preklinjanje sinov Amonovih, s katerim so zasmehovali ljudstvo moje in sebe veličili proti njegovemu kraju.',
        9: 'Zatorej, kakor res živim, govori Gospod nad vojskami, Bog Izraelov: Gotovo bode Moab kakor Sodoma in sinovi Amonovi kakor Gomora, koprivja posest in solne jame in večna puščava. Ljudstva mojega ostanek jih opleni in preostanek naroda mojega jih dobi v dedno last.',
        10: 'To se jim zgodi za njih prevzetnost, ker so zasmehovali ljudstvo Gospoda nad vojskami in se proti njemu veličili.',
        11: 'Strašen jim bode Gospod, kajti stori, da izginejo vsi bogovi zemlje; in po vseh otokih poganskih narodov ga bodo molili, vsakdo s svojega kraja.',
        12: 'Tudi vi, Etiopci, boste pobiti z mojim mečem.',
        13: 'In on iztegne roko proti severu in uniči Asirijo in Ninive naredi v samoto, suho kakor puščava.',
        14: 'In ležale bodo sredi mesta črede, vsake vrste živali; tudi pelikani in ježi bodo prenočevali na glavičih njih stebrov. Glas vetra bo pel v oknu, razvaline bodo na pragih, ker odtrgani so cedrovi obložci.',
        15: 'To je tisto veselo mesto, ki je prebivalo brez skrbi, ki je govorilo v srcu svojem: Jaz sem in nobenega ni razen mene! Kako je postalo v puščavo, v ležišče zverini! Vsak, kdor pojde mimo, bo žvižgal, mahal z roko.',
    },
    3: {
        1: 'Gorje tisti upornici in gnusnici, temu silovitemu mestu!',
        2: 'Nobenega glasu ni poslušalo, za nobeno svarilo ni bilo dovzetno; v Gospoda ni upalo, ni se bližalo svojemu Bogu.',
        3: 'Njegovi poglavarji sredi njega so rjoveči levi, njegovi sodniki kakor volkovi zvečer, ki še kosti ne ostavijo do jutra.',
        4: 'Njegovi proroki so bahavci, zvijačni možje; njegovi duhovniki skrunijo svetišče, na zlo zvijajo postavo.',
        5: 'Gospod je pravičen sredi njega, krivice ne dela nobene; vsako jutro stavi na svetlo pravico svojo, ne pogreši v tem. Krivičnik pa ne pozna sramu.',
        6: 'Iztrebil sem poganske narode, njih utrdbe so razvaljene; opustošil sem njih ceste, da nihče ne hodi po njih; njih mesta so razdejana, da v njih ni nikogar, nobenega prebivalca.',
        7: 'Rekel sem temu mestu: O da bi se le balo mene, da bi sprejelo svarjenje! tedaj bi se ne smelo razdejati bivališče njegovo, izbrisalo bi se vse, kar sem določil o njem. A vendar so že zgodaj pačili vse dejanje svoje.',
        8: 'Zato me čakajte, govori Gospod, do dne, ko vstanem, da bi plenil! Kajti sklep moj je, da zberem narode, skupim kraljestva, da izlijem nadnje srd svoj, vso gorečo jezo svojo; kajti v ognju gorečnosti moje bo požrta vsa zemlja.',
        9: 'Kajti takrat izpremenim narodom ustnice, da bodo čiste, da bi vsi klicali ime Gospodovo in mu služili enodušno.',
        10: 'Z one strani etiopskih rek privedejo molilce moje, hčer razkropljencev mojih, meni v darilo.',
        11: 'Tisti dan se ti ne bode treba sramovati vseh dejanj, s katerimi si se pregrešila zoper mene; kajti takrat odpravim izmed tebe ošabne širokoustneže tvoje, in se ne boš več prevzemala na gori svetosti moje.',
        12: 'In ostavim sredi tebe ponižno in ubogo ljudstvo, ti bodo upali v ime Gospodovo.',
        13: 'Ostanki Izraelovi ne bodo delali krivice, ne govorili laži in v njih ustih ne bo prevarljivega jezika, temuč bodo pasli in počivali in ga ne bode, ki bi jih strašil.',
        14: 'Glasno poj, o hči sionska, ukajte, ki ste Izraelovi! veséli se in raduj iz vsega srca, hči jeruzalemska!',
        15: 'Odvzel je Gospod sodbe tvoje, odstranil sovražnika tvojega. Kralj Izraelov, Jehova, je sredi tebe, nesreče ne boš več videla nobene.',
        16: 'Tisti dan poreko Jeruzalemu: Ne boj se! Sion, tvoje roke naj ne omagajo!',
        17: 'Jehova, tvoj Bog, je sredi tebe, junak, ki hoče rešiti; veseli se te presilno, molči v ljubezni svoji, raduje se nad teboj z glasnim petjem.',
        18: 'Zberem tiste, ki žalujejo po prazničnem zborovanju; iz tebe so bili, sramota jih je težila.',
        19: 'Glej, jaz bom ravnal tisti čas z vsemi stiskalci tvojimi, in rešim hrome in zberem izvržene in jim napravim hvalo in sloveče ime po vseh deželah, kjer so zdaj v sramoti.',
        20: 'Tisti čas vas privedem sem in tisti čas vas zberem; kajti v sloveče ime in v hvalo vas storim med vsemi ljudstvi na zemlji, ko nazaj pripeljem ujetništvo vaše pred vašimi očmi, pravi Gospod.',
    },
}
